/** 東亞那一塊的範圍（EA_COAST 涵蓋的地方；world.ts 在這裡面的點不畫） */
export const EA_BOX = { s: 18, w: 108, n: 46, e: 146 };

/** 解開差值編碼：每段一串 [緯度, 經度] */
function decode(s: string): Array<Array<[number, number]>> {
  return s.split(';').map((seg) => {
    const v = seg.split(',').map(Number);
    const out: Array<[number, number]> = [];
    let lat = 0;
    let lng = 0;
    for (let i = 0; i + 1 < v.length; i += 2) {
      lat += v[i];
      lng += v[i + 1];
      out.push([lat / 1000, lng / 1000]);
    }
    return out;
  });
}

/** 東亞的海岸線（開放的線；頭尾同一點的是整圈的島） */
export const eaCoast: Array<Array<[number, number]>> = decode(EA_COAST);

/**
 * 一塊範圍（好幾圈多邊形，奇偶規則）的「在不在裡面」：切成 0.05 度的格子，格子中心在不在裡面算一次記住；
 * 格子裡有邊經過的，再數這一點到格子中心之間跨過幾條邊（只看這一格的邊）
 */
export class RegionMask {
  private static readonly CELL = 0.05;
  private readonly rings: Array<Array<[number, number]>>;
  private readonly box: [number, number, number, number];
  private readonly cells = new Map<number, Array<[number, number, number, number]>>();
  private readonly centers = new Map<number, boolean>();

  constructor(rings: Array<Array<[number, number]>>) {
    this.rings = rings;
    let [s, w, n, e] = [Infinity, Infinity, -Infinity, -Infinity];
    const C = RegionMask.CELL;
    for (const r of rings) {
      for (let i = 0; i < r.length; i++) {
        const [la, ln] = r[i];
        [s, w, n, e] = [Math.min(s, la), Math.min(w, ln), Math.max(n, la), Math.max(e, ln)];
        if (i === 0) continue;
        const [pa, pn] = r[i - 1];
        for (let cy = Math.floor(Math.min(la, pa) / C); cy <= Math.floor(Math.max(la, pa) / C); cy++) {
          for (let cx = Math.floor(Math.min(ln, pn) / C); cx <= Math.floor(Math.max(ln, pn) / C); cx++) {
            const k = RegionMask.key(cy, cx);
            const list = this.cells.get(k) ?? [];
            list.push([pa, pn, la, ln]);
            this.cells.set(k, list);
          }
        }
      }
    }
    this.box = [s, w, n, e];
  }

  private static key(cy: number, cx: number): number {
    return (cy + 4000) * 20000 + (cx + 8000);
  }

  /** 射線法（全部的邊）：只拿來算格子中心，算過就記住 */
  private full(lat: number, lng: number): boolean {
    let inside = false;
    for (const r of this.rings) {
      for (let i = 1; i < r.length; i++) {
        const [a1, n1] = r[i - 1];
        const [a2, n2] = r[i];
        if (a1 > lat !== a2 > lat && lng < ((n2 - n1) * (lat - a1)) / (a2 - a1) + n1) inside = !inside;
      }
    }
    return inside;
  }

  contains(lat: number, lng: number): boolean {
    const [s, w, n, e] = this.box;
    if (lat < s || lat > n || lng < w || lng > e) return false;
    const C = RegionMask.CELL;
    const cy = Math.floor(lat / C);
    const cx = Math.floor(lng / C);
    const k = RegionMask.key(cy, cx);
    const [ma, mn] = [(cy + 0.5) * C, (cx + 0.5) * C];
    let inside = this.centers.get(k);
    if (inside === undefined) {
      inside = this.full(ma, mn);
      this.centers.set(k, inside);
    }
    // 這一點到格子中心之間跨過幾條邊：奇數條就跟中心相反
    for (const [a1, n1, a2, n2] of this.cells.get(k) ?? []) if (crosses(lat, lng, ma, mn, a1, n1, a2, n2)) inside = !inside;
    return inside;
  }
}

/** 兩段線段有沒有相交（端點剛好碰到不算，邊界上的點本來就說不準） */
function crosses(ay: number, ax: number, by: number, bx: number, cy: number, cx: number, dy: number, dx: number): boolean {
  const o = (py: number, px: number, qy: number, qx: number, ry: number, rx: number): number => (qx - px) * (ry - py) - (qy - py) * (rx - px);
  const d1 = o(cy, cx, dy, dx, ay, ax);
  const d2 = o(cy, cx, dy, dx, by, bx);
  const d3 = o(ay, ax, by, bx, cy, cx);
  const d4 = o(ay, ax, by, bx, dy, dx);
  return d1 * d2 < 0 && d3 * d4 < 0;
}

/** 中國的範圍（雷達在這裡面不畫路、不畫近距離的實線海岸） */
export const chinaMask = new RegionMask(decode(CHINA_MASK));
